from pathlib import Path
import json,hashlib,re
m=Path('outputs/2026-11-01_source_metadata');a=json.loads((m/'reused_source_metadata.json').read_text());b=json.loads((m/'download_manifest_initial.json').read_text());receipt=json.loads((m/'source_citation_hashes.json').read_text());assert receipt['status']=='verified'
for p in [m/'reused_source_metadata.json',m/'download_manifest_initial.json']:assert hashlib.sha256(p.read_bytes()).hexdigest()==receipt['metadata_sha256'][p.name]
s=Path('deliverables/2026-11-01_HeatSignal_manuscript_text_v22.txt').read_text();changes=[]
def edit(a,b):
 global s
 assert s.count(a)==1,(s.count(a),a);s=s.replace(a,b);changes.append(dict(old=a,new=b))
edit('UTC daily extrema do not identify exact local daytime maxima or nighttime minima.','UTC daily extrema do not identify exact local daytime maxima or nighttime minima. Population weights and administrative polygons retain their archived editions [7, 8].')
edit('Larger pre-event median absolute deviation means less stable baseline connectivity.','Larger pre-event median absolute deviation means less stable baseline connectivity. Social indicators retain their archived World Bank reference years [11].')
