edit('computational version and implementation details are recorded in the project run artifacts.','this documentation citation does not establish the package version used for every archived computation.')
w=next(r for r in a if r['provider']=='WorldPop');g=next(r for r in a if r['source_id']=='geoboundaries_cgaz_adm0');stop=next(r for r in b if r['file'].endswith('.xlsx'));ib=next(r for r in b if r['file'].startswith('ibtracs/'));wb=next(r for r in b if r['file']=='worldbank/IT.NET.USER.ZS.json')
refs=[f"[7] WorldPop. Global population counts for 2025, 1 km, release {w['version']} [dataset]. Retained file: {w['object_key']}; catalogue record 99397. {w['url']}",f"[8] geoBoundaries. Composite Global Administrative Zones (CGAZ), ADM0 and ADM1, snapshot 5c251340 [datasets]. Retained GeoPackages: geoBoundariesCGAZ_ADM0.gpkg and geoBoundariesCGAZ_ADM1.gpkg. The accompanying provenance ledger identifies both exact files. ADM0 source archive: {g['url']}",f"[9] Access Now, #KeepItOn. Shutdown Tracker Optimization Project (STOP), 2016–2025 workbook [dataset]. Archived 22 September 2026 (UTC), retained as STOP_2016_2025.xlsx. Exact source archive: {stop['url']}",f"[10] NOAA National Centers for Environmental Information. International Best Track Archive for Climate Stewardship (IBTrACS), version 04r01, since-1980 CSV [dataset]. Archived 22 September 2026 (UTC); the study uses the retained 2018–2025 extract. {ib['url']}",f"[11] World Bank. World Development Indicators, archived API country-year observations for 2018–2025 [datasets]. Indicators IT.NET.USER.ZS, EG.ELC.ACCS.ZS, SP.URB.TOTL.IN.ZS, NY.GDP.PCAP.PP.KD and SP.POP.TOTL, with archived country metadata. Retrieved 22 September 2026 (UTC); original missing values retained. The provenance ledger records each exact API request, archive date and SHA-256. Internet-use archive request: {wb['url']}"]
s+='\n\n'+'\n\n'.join(refs)+'\n';body,bib=s.split('\nReferences\n');cited={int(n) for r in re.findall(r'\[([0-9, ]+)\]',body) for n in re.findall(r'\d+',r)};assert cited==set(map(int,re.findall(r'^\[(\d+)\]',bib,re.M)))==set(range(1,12))
t=Path('deliverables/2026-11-01_HeatSignal_manuscript_text_v23.txt');assert not t.exists();t.write_text(s)
Path('outputs/2026-11-01_manuscript_dataset_citation_edits.json').write_text(json.dumps(dict(changes=changes,added_references=list(range(7,12)),all_reference_ids_resolve=True,source_ledger_sha256=hashlib.sha256((m/'source_citation_hashes.json').read_bytes()).hexdigest(),basis='Retained source editions and rehashed archives; no new data or inferred release dates',whole_study_accepted=False),ensure_ascii=False,indent=2)+'\n')
